Path('/kaggle/working/exact_author_joint.py').write_text('"""Exact shared-prompt Gaussian posteriors under author uniqueness.\n\nOriginal Gaussian model and whitening: prvsiyan/public_gaussian.py.\nOur inference replaces factorial assignment enumeration and large-group\nmean-field updates with subset dynamic programming (at most2**18 states).\n\nlogp(a|U) = sum_i -.5||U_i-m[a_i]||^2\n            +.5 sum_d gamma[d]*(sum_i U_i[d]-sum_i m[a_i,d])^2.\nFor unique authors, the second term depends only on the selected author set,\nso assignment permutations can be summed exactly with subset DP.\n"""\nfrom functools import lru_cache\nimport numpy as np\nfrom scipy.special import logsumexp\n\n@lru_cache(maxsize=4)\ndef _levels(k):\n    masks=np.arange(1<<k,dtype=np.int64)\n    counts=np.fromiter((int(x).bit_count() for x in masks),dtype=np.uint8,count=len(masks))\n    return tuple(masks[counts==n] for n in range(k+1))\n\nclass ExactAuthorPosterior:\n    def __init__(self,means,prompt_variances):\n        self.m=np.asarray(means,dtype=np.float64);self.lam=np.asarray(prompt_variances,dtype=np.float64)\n        self.k,self.d=self.m.shape\n        assert 1<=self.k<=18 and self.lam.shape==(self.d,) and (self.lam>=0).all()\n        assert np.isfinite(self.m).all() and np.isfinite(self.lam).all()\n        self.levels=_levels(self.k);self.subset_means={}\n    def group(self,U,temperature=1.,extra_log_scores=None,model_weight=1.,extra_weight=1.):\n        U=np.asarray(U,dtype=np.float64);n=len(U)\n        assert U.shape==(n,self.d) and 1<=n<=self.k and temperature>0 and np.isfinite(U).all()\n        assert model_weight>=0 and extra_weight>=0\n        extra=None if extra_log_scores is None else np.asarray(extra_log_scores,dtype=np.float64)\n        if extra is not None:assert extra.shape==(n,self.k) and np.isfinite(extra).all()\n        if n==1:\n            value=-.5*((U[:,None,:]-self.m[None,:,:])**2/(1+self.lam)).sum(2)/temperature\n            value*=model_weight\n            if extra is not None:value+=extra_weight*extra\n            return value-logsumexp(value,axis=1,keepdims=True)\n        if n not in self.subset_means:\n            masks=self.levels[n]\n            membership=((masks[:,None]>>np.arange(self.k))&1).astype(np.float64)\n            self.subset_means[n]=membership@self.m\n        terminal=self.levels[n];gamma=self.lam/(1+n*self.lam)\n        residual=U.sum(0)[None,:]-self.subset_means[n]\n        correction=.5*np.einsum(\'nd,d,nd->n\',residual,gamma,residual)/temperature\n        correction*=model_weight\n        correction-=correction.max()\n        A=-.5*((U[:,None,:]-self.m[None,:,:])**2).sum(2)/temperature\n        A*=model_weight\n        if extra is not None:A+=extra_weight*extra\n        A-=A.max(1,keepdims=True)\n        forward=np.full(1<<self.k,-np.inf);forward[0]=0.\n        for count in range(1,n+1):\n            masks=self.levels[count]\n            for author in range(self.k):\n                bit=1<<author;chosen=masks[(masks&bit)!=0]\n                forward[chosen]=np.logaddexp(forward[chosen],forward[chosen^bit]+A[count-1,author])\n        backward=np.full_like(forward,-np.inf);backward[terminal]=correction\n        for count in range(n-1,-1,-1):\n            masks=self.levels[count]\n            for author in range(self.k):\n                bit=1<<author;chosen=masks[(masks&bit)==0]\n                backward[chosen]=np.logaddexp(backward[chosen],A[count,author]+backward[chosen|bit])\n        assert np.isfinite(backward[0])\n        result=np.empty((n,self.k))\n        for row in range(n):\n            masks=self.levels[row]\n            for author in range(self.k):\n                bit=1<<author;chosen=masks[(masks&bit)==0]\n                result[row,author]=logsumexp(forward[chosen]+A[row,author]+backward[chosen|bit])-backward[0]\n        # Uniqueness is global, but each row\'s posterior must still normalise.\n        assert np.max(np.abs(logsumexp(result,axis=1)))<1e-8\n        result-=logsumexp(result,axis=1,keepdims=True)\n        return result\n\ndef scores(U,groups,prm,extra_log_scores=None,model_weight=1.,extra_weight=1.):\n    U=np.asarray(U);groups=np.asarray(groups);result=np.empty((len(U),len(prm[\'m\'])))\n    solver=ExactAuthorPosterior(prm[\'m\'],prm[\'lam\'])\n    for group in np.unique(groups):\n        rows=np.flatnonzero(groups==group)\n        result[rows]=solver.group(U[rows],float(prm[\'T1\'] if len(rows)==1 else prm[\'Tg\']),extra_log_scores=None if extra_log_scores is None else extra_log_scores[rows],model_weight=model_weight,extra_weight=extra_weight)\n    return result\n')
Path('/kaggle/working/stage_local_checkpoint.py').write_text('"""Sequentially stage a small immutable checkpoint, preserving every file byte.\n\nIntended for the slow mounted Ultrabert fold checkpoints. No weight changes;\nsource/destination hashes are recorded. Uses scratch outside saved outputs.\n"""\nfrom pathlib import Path\nimport hashlib,json,shutil,time\n\ndef stage_checkpoint(source,max_bytes=3*2**30):\n    source=Path(source).resolve()\n    assert source.is_relative_to(Path(\'/kaggle/input\').resolve())\n    files=[p for p in source.rglob(\'*\') if p.is_file()]\n    total=sum(p.stat().st_size for p in files)\n    if total>max_bytes:\n        print(\'CHECKPOINT_STAGE_SIZE_GUARD\',str(source),total,flush=True);return source\n    target=Path(\'/kaggle/temp/ntl-small-checkpoints\')/hashlib.sha256(str(source).encode()).hexdigest()[:16]\n    ready=target/\'stage-audit.json\'\n    if ready.exists():return target\n    target.mkdir(parents=True,exist_ok=True)\n    if shutil.disk_usage(target).free<total+2**30:\n        print(\'CHECKPOINT_STAGE_DISK_GUARD\',str(source),flush=True);return source\n    began=time.monotonic();records={}\n    try:\n        for origin in files:\n            relative=origin.relative_to(source);destination=target/relative;destination.parent.mkdir(parents=True,exist_ok=True);digest=hashlib.sha256();count=0\n            with origin.open(\'rb\') as src,destination.open(\'wb\') as dst:\n                while chunk:=src.read(16*1024*1024):dst.write(chunk);digest.update(chunk);count+=len(chunk)\n            assert count==origin.stat().st_size\n            with destination.open(\'rb\') as dst:assert hashlib.file_digest(dst,\'sha256\').hexdigest()==digest.hexdigest()\n            records[str(relative)]={\'bytes\':count,\'sha256\':digest.hexdigest()}\n        ready.write_text(json.dumps(dict(source=str(source),files=records,seconds=time.monotonic()-began),indent=2));print(\'VERIFIED_SMALL_CHECKPOINT_STAGE\',str(source),total,round(time.monotonic()-began,2),flush=True);return target\n    except Exception as exc:\n        print(\'CHECKPOINT_STAGE_FALLBACK\',str(source),type(exc).__name__,flush=True);return source\n')
Path('/kaggle/working/pool_hidden_safely.py').write_text('"""Move pooled vectors instead of complete token activations to the CPU.\n\nLayerNorm remains on its original CPU path. Each new tensor geometry/device is\nchecked against the original arithmetic before the reduced-copy path is used.\nThe original implementation is retained as a numerical fallback.\n"""\nimport json\nfrom pathlib import Path\nimport torch\n\n_checks = {}\n_enabled = True\n\ndef pool_hidden(h, mask):\n    global _enabled\n    def original():\n        return (h.float().cpu() * mask).sum(1) / mask.sum(1)\n    if not _enabled or h.device.type == \'cpu\':\n        return original()\n    gpu_mask = mask.to(h.device)\n    result = ((h.float() * gpu_mask).sum(1) / gpu_mask.sum(1)).cpu()\n    key = str((str(h.device), str(h.dtype), h.shape[-1]))\n    if key not in _checks:\n        reference = original()\n        accepted = torch.allclose(result, reference, rtol=1e-4, atol=1e-5)\n        _checks[key] = dict(accepted=bool(accepted), shape=list(h.shape),\n            max_absolute_error=float((result-reference).abs().max()),\n            relative_error=float(torch.linalg.vector_norm(result-reference) /\n                torch.linalg.vector_norm(reference).clamp_min(1e-12)))\n        print(\'GPU_POOL_PARITY\', key, _checks[key], flush=True)\n        Path(\'/kaggle/working/gpu_pool_parity.json\').write_text(\n            json.dumps(_checks, indent=2))\n        if not accepted:\n            _enabled = False\n            return reference\n    return result\n')
Path('/kaggle/working/stage_local_checkpoint.py').write_text('"""Sequentially stage a small immutable checkpoint, preserving every file byte.\n\nIntended for the slow mounted Ultrabert fold checkpoints. No weight changes;\nsource/destination hashes are recorded. Uses scratch outside saved outputs.\n"""\nfrom pathlib import Path\nimport hashlib,json,shutil,time\n\ndef stage_named_files(source,names):\n    """Copy selected flattened public files to scratch under local aliases."""\n    source=Path(source).resolve();assert source.is_relative_to(Path(\'/kaggle/input\').resolve())\n    for origin,alias in names.items():\n        assert Path(origin).name==origin and Path(alias).name==alias\n        assert (source/origin).is_file()\n    key=hashlib.sha256((str(source)+json.dumps(names,sort_keys=True)).encode()).hexdigest()[:16]\n    target=Path(\'/kaggle/temp/ntl-selected-checkpoints\')/key;target.mkdir(parents=True,exist_ok=True)\n    ready=target/\'stage-audit.json\'\n    if not ready.exists():\n        total=sum((source/name).stat().st_size for name in names)\n        assert shutil.disk_usage(target).free>total+2**30\n        records={};began=time.monotonic()\n        for name,alias in names.items():\n            digest=hashlib.sha256();count=0\n            with (source/name).open(\'rb\') as src,(target/alias).open(\'wb\') as dst:\n                while chunk:=src.read(16*1024*1024):dst.write(chunk);digest.update(chunk);count+=len(chunk)\n            assert count==(source/name).stat().st_size\n            with (target/alias).open(\'rb\') as check:assert hashlib.file_digest(check,\'sha256\').hexdigest()==digest.hexdigest()\n            records[name]=dict(local_alias=alias,bytes=count,sha256=digest.hexdigest())\n        ready.write_text(json.dumps(dict(source=str(source),files=records,seconds=time.monotonic()-began),indent=2))\n        print(\'VERIFIED_SELECTED_CHECKPOINT_STAGE\',total,round(time.monotonic()-began,2),flush=True)\n    audit_dir=Path(\'/kaggle/working/model_stage_audits\');audit_dir.mkdir(exist_ok=True)\n    (audit_dir/(key+\'.json\')).write_bytes(ready.read_bytes())\n    return target\n\ndef stage_checkpoint(source,max_bytes=3*2**30):\n    source=Path(source).resolve()\n    assert source.is_relative_to(Path(\'/kaggle/input\').resolve())\n    files=[p for p in source.rglob(\'*\') if p.is_file()]\n    total=sum(p.stat().st_size for p in files)\n    if total>max_bytes:\n        print(\'CHECKPOINT_STAGE_SIZE_GUARD\',str(source),total,flush=True);return source\n    target=Path(\'/kaggle/temp/ntl-small-checkpoints\')/hashlib.sha256(str(source).encode()).hexdigest()[:16]\n    ready=target/\'stage-audit.json\'\n    if ready.exists():\n        audit_dir=Path(\'/kaggle/working/model_stage_audits\');audit_dir.mkdir(exist_ok=True)\n        (audit_dir/(target.name+\'.json\')).write_bytes(ready.read_bytes())\n        return target\n    target.mkdir(parents=True,exist_ok=True)\n    if shutil.disk_usage(target).free<total+2**30:\n        print(\'CHECKPOINT_STAGE_DISK_GUARD\',str(source),flush=True);return source\n    began=time.monotonic();records={}\n    try:\n        for origin in files:\n            relative=origin.relative_to(source);destination=target/relative;destination.parent.mkdir(parents=True,exist_ok=True);digest=hashlib.sha256();count=0\n            with origin.open(\'rb\') as src,destination.open(\'wb\') as dst:\n                while chunk:=src.read(16*1024*1024):dst.write(chunk);digest.update(chunk);count+=len(chunk)\n            assert count==origin.stat().st_size\n            with destination.open(\'rb\') as dst:assert hashlib.file_digest(dst,\'sha256\').hexdigest()==digest.hexdigest()\n            records[str(relative)]={\'bytes\':count,\'sha256\':digest.hexdigest()}\n        ready.write_text(json.dumps(dict(source=str(source),files=records,seconds=time.monotonic()-began),indent=2))\n        audit_dir=Path(\'/kaggle/working/model_stage_audits\');audit_dir.mkdir(exist_ok=True)\n        (audit_dir/(target.name+\'.json\')).write_bytes(ready.read_bytes())\n        print(\'VERIFIED_LOCAL_CHECKPOINT_STAGE\',str(source),total,round(time.monotonic()-began,2),flush=True);return target\n    except Exception as exc:\n        print(\'CHECKPOINT_STAGE_FALLBACK\',str(source),type(exc).__name__,flush=True);return source\n')


